css:
@import url("https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Albert+Sans:wght@400;500;600;700&display=swap");
:root{--green:#1D3A31;--green-2:#2B5246;--sage:#DCE6DD;--sage-2:#EEF3EE;--wine:#8C2F39;--white:#fff;--text:#22302B;--muted:#5C6B65;--line:#C9D5CB;
--serif:"Instrument Serif",Georgia,serif;--sans:"Albert Sans",system-ui,-apple-system,"Segoe UI",sans-serif;--wrap:1200px}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;font-family:var(--sans);font-size:17px;line-height:1.7;color:var(--text);background:var(--white);-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}a{color:inherit}p{margin:0 0 1em}
h1,h2,h3{font-family:var(--serif);font-weight:400;margin:0;line-height:1.08;color:var(--green);letter-spacing:-.005em}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 26px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--wine);color:#fff;padding:10px 14px;z-index:99}
:focus-visible{outline:2px solid var(--wine);outline-offset:3px}
.site-header{position:sticky;top:0;z-index:40;background:rgba(255,255,255,.95);backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}
.nav{display:flex;align-items:center;justify-content:space-between;height:80px}
.logo{font-family:var(--serif);font-size:28px;text-decoration:none;color:var(--green)}.logo i{color:var(--wine)}
.menu{display:flex;gap:32px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none;font-weight:500}.menu a:hover{color:var(--wine)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 26px;border-radius:999px;text-decoration:none;font-weight:600;font-size:16px;border:1.5px solid transparent;cursor:pointer;font-family:var(--sans)}
.btn-green{background:var(--green);color:#fff}.btn-green:hover{background:var(--green-2)}
.btn-wine{background:var(--wine);color:#fff}.btn-wine:hover{background:#74252e}
.btn-out{border-color:var(--green);color:var(--green)}.btn-out:hover{background:var(--green);color:#fff}
.burger{display:none;background:none;border:1px solid var(--line);border-radius:8px;padding:9px 11px;cursor:pointer}.burger span{display:block;width:22px;height:2px;background:var(--green);margin:4px 0}

.hero{padding:80px 0 0;background:linear-gradient(180deg,var(--sage-2),#fff 70%)}
.hero h1{font-size:clamp(48px,7.6vw,112px);max-width:14ch}
.hero h1 em{color:var(--wine)}
.hero-row{display:grid;grid-template-columns:1fr 1fr;gap:60px;margin-top:40px;align-items:end}
.hero-row p{font-size:20px;color:var(--muted);max-width:44ch;margin:0}
.hero-actions{display:flex;gap:14px;flex-wrap:wrap;justify-content:flex-end}
.hero-img{margin-top:60px;position:relative}
.hero-img img{width:100%;aspect-ratio:21/8;object-fit:cover;border-radius:22px 22px 0 0}
.hero-card{position:absolute;right:40px;bottom:-40px;background:var(--green);color:#e6efe8;border-radius:18px;padding:28px 30px;max-width:340px;box-shadow:0 30px 60px -30px rgba(29,58,49,.7)}
.hero-card b{font-family:var(--serif);font-size:54px;font-weight:400;color:#fff;display:block;line-height:1}

section{padding:120px 0}
.eyebrow{font-weight:600;color:var(--wine);font-size:15px;margin-bottom:14px;display:block}
h2{font-size:clamp(38px,4.8vw,64px)}
.two{display:grid;grid-template-columns:1fr 1fr;gap:70px}

.problems{padding-top:150px}
.plist{list-style:none;padding:0;margin:0;border-top:1px solid var(--line)}
.plist li{display:grid;grid-template-columns:80px 1fr;gap:20px;padding:26px 0;border-bottom:1px solid var(--line)}
.plist .n{font-family:var(--serif);font-size:34px;color:var(--wine);line-height:1}
.plist h3{font-family:var(--sans);font-size:20px;font-weight:700;color:var(--green);margin-bottom:6px}
.plist p{color:var(--muted);margin:0}

.services{background:var(--green);color:#cfdcd3}
.services h2{color:#fff}.services .eyebrow{color:#e7b3b9}
.svc{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--green-2);margin-top:56px;border:1px solid var(--green-2)}
.svc article{background:var(--green);padding:36px 32px}
.svc h3{color:#fff;font-size:32px;margin-bottom:12px}
.svc p{font-size:16px}
.svc ul{padding-left:18px;margin:14px 0 0;font-size:15px;color:#b9cabe}

.results{display:grid;grid-template-columns:1.1fr .9fr;gap:60px;align-items:center}
.results figure{margin:0;border-radius:20px;overflow:hidden}.results figure img{aspect-ratio:4/3;object-fit:cover;width:100%}
.cases{display:grid;gap:18px;margin-top:34px}
.case{background:var(--sage-2);border-radius:16px;padding:24px 26px;display:grid;grid-template-columns:130px 1fr;gap:20px;align-items:center}
.case b{font-family:var(--serif);font-size:48px;font-weight:400;color:var(--wine);line-height:1}
.case h3{font-family:var(--sans);font-size:18px;font-weight:700;margin-bottom:4px}
.case p{margin:0;color:var(--muted);font-size:15px}

.industries{background:var(--sage-2)}
.chips{display:flex;flex-wrap:wrap;gap:12px;margin-top:40px}
.chips span{background:#fff;border:1px solid var(--line);border-radius:999px;padding:12px 22px;font-weight:600;color:var(--green)}

.team-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin-top:56px}
.person img{aspect-ratio:3/4;object-fit:cover;border-radius:14px;width:100%}
.person h3{font-size:28px;margin-top:16px}
.person p{margin:0;color:var(--muted);font-size:15px}

.quote{background:var(--sage);text-align:center}
.quote blockquote{margin:0 auto;max-width:900px}
.quote blockquote p{font-family:var(--serif);font-size:clamp(28px,3.6vw,46px);line-height:1.25;color:var(--green)}
.quote cite{font-style:normal;color:var(--muted)}.quote cite b{color:var(--green)}

.posts{display:grid;grid-template-columns:repeat(3,1fr);gap:26px;margin-top:50px}
.post img{aspect-ratio:16/10;object-fit:cover;border-radius:14px;width:100%}
.post time{display:block;margin-top:16px;font-size:14px;color:var(--muted)}
.post h3{font-size:28px;margin:6px 0 8px}.post h3 a{text-decoration:none}.post h3 a:hover{color:var(--wine)}
.post p{color:var(--muted);font-size:16px;margin:0}

.faq details{border-bottom:1px solid var(--line);padding:22px 0}
.faq summary{list-style:none;cursor:pointer;font-weight:700;font-size:19px;color:var(--green);display:flex;justify-content:space-between;gap:20px}
.faq summary::-webkit-details-marker{display:none}.faq summary::after{content:"+";font-size:26px;line-height:1;color:var(--wine)}
.faq details[open] summary::after{content:"−"}.faq details p{margin:12px 0 0;color:var(--muted)}

.contact{background:var(--green);color:#cfdcd3}.contact h2{color:#fff}.contact .eyebrow{color:#e7b3b9}
.contact .two{align-items:start}
.contact ul{list-style:none;padding:0;margin:30px 0 0}.contact li{padding:12px 0;border-top:1px solid var(--green-2)}.contact li b{display:block;color:#fff}
form{background:#fff;border-radius:20px;padding:34px;color:var(--text)}
label{display:block;font-weight:600;font-size:14px;color:var(--green);margin-bottom:6px}
input,select,textarea{width:100%;font:inherit;padding:12px 14px;border:1.5px solid var(--line);border-radius:10px;margin-bottom:16px;color:var(--text);background:#fff}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--green)}
form .btn{width:100%;justify-content:center}
.row2{display:grid;grid-template-columns:1fr 1fr;gap:14px}
footer{background:#152C25;color:#9fb3a7;padding:56px 0 28px;font-size:15px}
.foot{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:40px;margin-bottom:40px}
footer h3{font-family:var(--sans);font-size:15px;font-weight:700;color:#fff;margin-bottom:12px}
footer ul{list-style:none;padding:0;margin:0}footer li{margin-bottom:8px}footer a{text-decoration:none}footer a:hover{color:#fff}
.legal{border-top:1px solid #24453b;padding-top:22px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px}
@media (max-width:980px){.menu,.nav .btn{display:none}.burger{display:block}
.menu.open{display:flex;flex-direction:column;position:absolute;top:80px;left:0;right:0;background:#fff;padding:22px 26px;border-bottom:1px solid var(--line);gap:16px}
.two,.hero-row,.results{grid-template-columns:1fr;gap:40px}.hero-actions{justify-content:flex-start}
.svc,.posts{grid-template-columns:1fr}.team-grid{grid-template-columns:1fr 1fr}.foot{grid-template-columns:1fr 1fr}
.hero-card{position:relative;right:auto;bottom:auto;margin:-60px 20px 0;max-width:none}}
@media (max-width:600px){body{font-size:16px}section{padding:80px 0}.team-grid,.row2,.foot{grid-template-columns:1fr}.case{grid-template-columns:1fr}.hero-img img{aspect-ratio:4/3}}
